#include <stdio.h>

/* 形参写成 int a[] 和写成 int *a 是同一件事：传进来的是数组首地址 */
int max_of(int a[], int n) {
    int m = a[0];                  /* 用第一个元素初始化，不能写 0 */
    for (int i = 1; i < n; i++) {
        if (a[i] > m) {
            m = a[i];
        }
    }
    return m;
}

int min_of(int a[], int n) {
    int m = a[0];                  /* 初始化为 0 的话，全是负数时结果就错了 */
    for (int i = 1; i < n; i++) {
        if (a[i] < m) {
            m = a[i];
        }
    }
    return m;
}

int sum_of(int a[], int n) {
    int s = 0;                     /* 累加器必须初始化为 0，否则是内存里的随机值 */
    for (int i = 0; i < n; i++) {
        s += a[i];
    }
    return s;
}

int main() {
    int n;
    scanf("%d", &n);

    int a[100];
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);        /* a[i] 是普通变量，取地址符不能漏 */
    }

    printf("%d\n", max_of(a, n));
    printf("%d\n", min_of(a, n));
    printf("%d\n", sum_of(a, n));
    return 0;
}

