#include <stdio.h>

/* 是素数返回 1，不是返回 0 */
int is_prime(int n) {
    if (n < 2) {
        return 0;                  /* 1 不是素数，这条边界最容易漏 */
    }
    for (int i = 2; i * i <= n; i++) {   /* i*i <= n 等价于 i <= √n */
        if (n % i == 0) {
            return 0;              /* 找到因子就立刻返回，不用再试 */
        }
    }
    return 1;
}

int main() {
    int a, b;
    scanf("%d %d", &a, &b);

    /* 第一遍：数出个数，因为个数要最先输出 */
    int count = 0;
    for (int i = a; i <= b; i++) {
        if (is_prime(i)) {
            count++;
        }
    }
    printf("%d\n", count);

    /* 第二遍：按顺序打印，第一个数前面不加空格 */
    int first = 1;
    for (int i = a; i <= b; i++) {
        if (is_prime(i)) {
            if (!first) {
                printf(" ");
            }
            printf("%d", i);
            first = 0;
        }
    }
    printf("\n");
    return 0;
}

