#include <stdio.h>

int main() {
    char s[128];   /* 题目保证不超过 100 个字符，留出余量更安全 */

    /* fgets 会把行尾的换行符一起读进来；读到 EOF 时返回 NULL */
    if (fgets(s, sizeof(s), stdin) == NULL) {
        s[0] = '\0';   /* 什么都没读到就当成空字符串处理 */
    }

    int upper = 0, lower = 0, digit = 0, other = 0;
    for (int i = 0; s[i] != '\0' && s[i] != '\n'; i++) {
        char c = s[i];
        if (c >= 'A' && c <= 'Z') {
            upper++;
        } else if (c >= 'a' && c <= 'z') {
            lower++;
        } else if (c >= '0' && c <= '9') {
            digit++;
        } else {
            other++;   /* 空格、逗号、感叹号都算在这里 */
        }
    }

    printf("%d\n", upper);
    printf("%d\n", lower);
    printf("%d\n", digit);
    printf("%d\n", other);
    return 0;
}

