#include <stdio.h>

int main() {
    int m, n;
    scanf("%d %d", &m, &n);

    /* 行列都不超过 10，下标最大是 9，所以开 [10][10] 刚好够 */
    int a[10][10];
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &a[i][j]);
        }
    }

    /* 转置不必再开一个数组：把输出时的访问顺序换一下就行。
       外层是列 j，内层是行 i，打印出来的自然就是 a[j][i]。 */
    for (int j = 0; j < n; j++) {
        for (int i = 0; i < m; i++) {
            if (i > 0) {
                printf(" ");   /* 每行第一个数前面不加空格 */
            }
            printf("%d", a[i][j]);
        }
        printf("\n");
    }
    return 0;
}

