#include <stdio.h>

/* 每种运算一个小函数，switch 里只负责分派 */
int add(int a, int b) { return a + b; }
int sub(int a, int b) { return a - b; }
int mul(int a, int b) { return a * b; }

int main() {
    int a, b;
    char op;

    /* %c 前面的空格不能省：它让 scanf 跳过前面的空白，
       否则 op 读到的会是 a 和运算符之间那个空格。 */
    scanf("%d %c %d", &a, &op, &b);

    switch (op) {
        case '+':
            printf("%d\n", add(a, b));
            break;                 /* 漏掉 break 会继续往下执行 */
        case '-':
            printf("%d\n", sub(a, b));
            break;
        case '*':
            printf("%d\n", mul(a, b));
            break;
        case '/':
            /* 写成 a / b 是两个整数相除，8 / 3 会得到 2；
               乘上 1.0 之后整个表达式按浮点计算。 */
            printf("%.2f\n", 1.0 * a / b);
            break;
        default:
            printf("error\n");     /* 输入保证合法，这里只是防御性写法 */
            break;
    }
    return 0;
}

