#include <stdio.h>
#include <string.h>

/* 姓名和成绩绑在一起，排序时整个结构体一起搬，不会出现
   「成绩换了、姓名没跟着换」这种对不上的情况。 */
struct Student {
    char name[20];   /* 最长 19 个字符，还要留一个位置给结尾的 '\0' */
    int score;
};

int main() {
    int n;
    scanf("%d", &n);

    struct Student s[50];
    for (int i = 0; i < n; i++) {
        /* 数组名 s[i].name 本身就是地址，这里不需要也不能写成 &s[i].name */
        scanf("%s %d", s[i].name, &s[i].score);
    }

    /* 选择排序：每一轮在剩下的学生里挑出应该排在最前面的那个 */
    for (int i = 0; i < n - 1; i++) {
        int best = i;
        for (int j = i + 1; j < n; j++) {
            if (s[j].score > s[best].score) {
                best = j;
            } else if (s[j].score == s[best].score &&
                       strcmp(s[j].name, s[best].name) < 0) {
                best = j;   /* 成绩相同时，姓名字典序小的排前面 */
            }
        }
        if (best != i) {
            struct Student tmp = s[i];
            s[i] = s[best];
            s[best] = tmp;   /* 结构体可以整体赋值，不用逐个成员搬 */
        }
    }

    for (int i = 0; i < n; i++) {
        printf("%s %d\n", s[i].name, s[i].score);
    }
    return 0;
}

